import{_ as a}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as i}from"./chunks/BDM.scaBLLhv.js";import{_ as o,a as r,b as n,c as t,d as s}from"./chunks/M-SS-LimiTTer.Bke--kwa.js";import{_ as l,o as c,c as p,a3 as d}from"./chunks/framework.g9mfNVRQ.js";const S=JSON.parse('{"title":"Inizializza sensore","description":"","frontmatter":{"source_hash":"ec23b1baed","source_commit":"ea9ce3a","i18n_outdated":true},"headers":[],"relativePath":"it/use/startsensor.md","filePath":"it/use/startsensor.md"}'),m={name:"it/use/startsensor.md"};function u(v,e,b,g,h,z){return c(),p("div",null,[...e[0]||(e[0]=[d('<p>Avviare un sensore in xDrip ha funzioni molto diverse a seconda del sensore.</p><h3 id="g6-and-1" tabindex="-1">G6 e 1 <a class="header-anchor" href="#g6-and-1" aria-label="Permalink to &quot;G6 e 1 {#g6-and-1}&quot;">​</a></h3><p>La documentazione di riferimento si trova <a href="https://navid200.github.io/xDrip/docs/Proper-connectivity.html" target="_blank" rel="noreferrer">qui</a>.</p><h3 id="g7-and-1" tabindex="-1">G7 e 1+ <a class="header-anchor" href="#g7-and-1" aria-label="Permalink to &quot;G7 e 1+ {#g7-and-1}&quot;">​</a></h3><p>Il sensore si avvia automaticamente nel momento in cui viene inserito. Non devi avviarlo in xDrip.</p><br><h3 id="libre" tabindex="-1">Libre <a class="header-anchor" href="#libre" aria-label="Permalink to &quot;Libre {#libre}&quot;">​</a></h3><p>Nota: questa sezione NON vale per Libre 2/2+ (UE) collegato a xDrip senza bridge. In quel caso, consulta le istruzioni di <a href="./../install/libre2.html#starting-libre-2-sensors">Libre 2 Direct</a></p><p>xDrip non è in grado di avviare un sensore Libre, né di fermarlo (in realtà questo sensore non si può fermare: se non si guasta, funziona per tutta la sua durata e si ferma da solo dopo 14 giorni e 12 ore; i sensori Libre 3 durano 15 giorni).</p><p>Per avviare il sensore devi usare il lettore o l&#39;app del produttore; anche alcune app di terze parti come Glimp-S ed eDropletNFC possono avviare il sensore Libre 1. Juggluco può avviare i sensori Libre 2 e 3.</p><p>L&#39;avvio del sensore in xDrip serve solo a tenere traccia della sua durata e a garantire che le calibrazioni siano aggiornate. Questa operazione è necessaria e consigliata ogni volta che sostituisci il sensore.</p><br><div class="admonition xdrip"><p class="admonition-title"><img src="'+a+'" style="zoom:75%;"></p><p> Inizializza Sensore</p></div><p>Conferma INIZIALIZZA SENSORE</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+i+'" style="zoom:75%;">Inizializza Nuovo Sensore</p><p>Non premere avviare sensore prima che il sensore sia inserito e il trasmettitore connesso.</p><p>    <span style="background-color:grey;color:white;align:center;">  INIZIALIZZA SENSORE </span></p></div><p>Se hai inserito il sensore oggi (cioè non avviato o avviato da poco), rispondi SI, OGGI</p><div class="admonition xdripitem"><p class="admonition-title">L&#39;hai inserito oggi?</p><p>Abbiamo bisogno di sapere quando il sensore è stato inserito per migliorare l&#39;accuratezza del calcolo.</p><p><span style="color:cyan;float:right;">NON OGGI  SI, OGGI </span></p></div><p>Se hai risposto oggi, seleziona l&#39;ora in cui hai avviato fisicamente il sensore trascinando l&#39;indicatore blu sull&#39;ora corretta. Con la visualizzazione a 12 ore, tocca <code>am</code> o<code>pm</code>. Con la visualizzazione a 24 ore, rilascia l&#39;ora corretta sull&#39;anello interno o esterno. Tocca OK.</p><img src="'+o+'" style="zoom:75%;"><p>Trascina l&#39;indicatore blu dei minuti sul valore corretto e tocca <code>OK</code>.</p><img src="'+r+'" style="zoom:75%;"><p>Il sensore appena avviato continuerà il riscaldamento se è stato avviato da meno di un&#39;ora.</p><div class="warning custom-block"><p class="custom-block-title">Attenzione</p><p><strong>Anche se xDrip proverà a leggere un sensore durante la fase di riscaldamento, i valori possono essere da inaffidabili a incoerenti e non vanno usati.</strong></p></div><img src="'+n+'" style="zoom:70%;"><p>Se usi <a href="./OOP.html#oop1">OOP1</a> o <a href="./OOP.html#oop2">OOP2</a> senza calibrazione, la glicemia verrà mostrata subito, senza bisogno della calibrazione iniziale.</p><p>Se usi un sensore già avviato, riceverai una richiesta di calibrazione entro 15 minuti.</p><p>Se vedi una freccia viola, potresti aver sbagliato la data e l&#39;ora di avvio del sensore: i dati di glicemia sono disponibili ma non vengono mostrati durante il riscaldamento di 1 ora.</p><img src="'+t+'" style="zoom:70%;"><br><p>Ora xDrip attenderà le letture e aggiornerà l&#39;avanzamento. Resta su questa schermata. Le letture arrivano a 5 minuti l&#39;una dall&#39;altra, quindi dovrebbero bastare meno di 20 minuti.</p><div class="admonition xdripitem"><p class="admonition-title">Sto raccogliendo le prime letture</p><p> ✔ Raccolta dati in esecuzione<br>  ⧖ Ricezione dati dal collector MiaoMiao<br>   Ho ricevuto alcuni dati recenti<br>   Ho ricevuto abbastanza dati per calibrare<br>  <em><strong>No data received yet</strong></em></p></div><p>Se come sorgente dati compare LimiTTer e non stai usando un vero <a href="https://github.com/JoernL/LimiTTer" target="_blank" rel="noreferrer">LimiTTer</a>, il tuo bridge non è collegato correttamente.</p><img src="'+s+'" style="zoom:70%;"><p>L&#39;indicazione <em><strong>No data received yet</strong></em> diventerà <em><strong>Need 3 recent readings</strong></em>. Se non arriva nessun dato, <a href="./../install/libreBT.html#bridge-settings">controlla i parametri</a>.</p><div class="admonition xdripitem"><p class="admonition-title">Sto raccogliendo le prime letture</p><p> ✔ Raccolta dati in esecuzione<br>  ✔ Ricezione dati dal collector MiaoMiao<br>  ✔ Ho ricevuto alcuni dati recenti<br>  ⧖ Ho ricevuto abbastanza dati per calibrare<br>  <em><strong>Need 3 recent readings, got only 1 so far</strong></em><br>  Next reading expected in 1 minute</p></div><p>Quando sono state ricevute abbastanza letture, compare la richiesta di calibrazione. Per saperne di più sulla calibrazione, vedi <a href="./../calibrate/101.html">qui</a>.</p><p>Se la tua glicemia è nell&#39;intervallo normale (per un sensore nuovo è consigliata la parte bassa dell&#39;intervallo normale) ed è stabile da almeno 10 minuti, senza carboidrati né insulina attivi, puoi calibrare.</p><p>Se la tua glicemia varia rapidamente o non è nell&#39;intervallo normale, non è consigliato calibrare adesso.</p><div class="admonition xdrip"><p class="admonition-title">Calibrare il sensore?</p><p>Abbiamo alcune letture!<br> Ci servirà il valore della prima misura capillare.<br> Pronto per calibrare ora?</p></div><p>Per la prima calibrazione possono essere richieste due letture; puoi usarne una sola se sei sicuro che sia valida. Inserisci semplicemente due volte lo stesso valore. Puoi impostare un solo valore come predefinito <a href="./../calibrate/advancedcal.html#calibrations">disattivando la doppia calibrazione</a>.</p><p>La glicemia dovrebbe comparire nel grafico principale.</p><br><h3 id="followers-and-companion-apps" tabindex="-1">Follower e app compagno <a class="header-anchor" href="#followers-and-companion-apps" aria-label="Permalink to &quot;Follower e app compagno {#followers-and-companion-apps}&quot;">​</a></h3><p>A volte è necessario &quot;avviare&quot; una sessione del sensore in xDrip per ricevere le letture.</p><p>Avviare o fermare un sensore in xDrip, quando si usa una sorgente follower o un&#39;app compagno, non ha alcun effetto sul sensore.</p><div class="warning custom-block"><p class="custom-block-title">Attenzione</p><p>L&#39;unica eccezione è il <a href="./sync.html#accept-followers-actions">follower xDrip Sync, che può trasmettere il comando di avvio o arresto al sensore vero e proprio se questo è collegato direttamente allo xDrip che fa da master</a>.<br> Non usare Avvia e Ferma sensore con un follower xDrip Sync, a meno che tu non sia certo che la persona con il telefono xDrip master sappia cosa fare con un sensore fermato!</p></div><div class="admonition xdrip"><p class="admonition-title"><img src="'+a+'" style="zoom:75%;"></p><p> Inizializza Sensore</p></div><p>Conferma INIZIALIZZA SENSORE</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+i+'" style="zoom:75%;">Inizializza Nuovo Sensore</p><p>Non premere avviare sensore prima che il sensore sia inserito e il trasmettitore connesso.</p><p>    <span style="background-color:grey;color:white;align:center;">  INIZIALIZZA SENSORE </span></p></div><p>Rispondi NON OGGI</p><div class="admonition xdripitem"><p class="admonition-title">L&#39;hai inserito oggi?</p><p>Abbiamo bisogno di sapere quando il sensore è stato inserito per migliorare l&#39;accuratezza del calcolo.</p><p><span style="color:cyan;float:right;">NON OGGI  SI, OGGI </span></p></div><p>xDrip dovrebbe ricevere le letture con la misurazione successiva.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Ultima modifica 23/11/2026</em></a></p>',54)])])}const N=l(m,[["render",u]]);export{S as __pageData,N as default};
